import{_ as t}from"./chunks/neural_mode_registration.8-KQLHqv.js";import{_ as o,c as a,o as i,al as n}from"./chunks/framework.CT7RwC5a.js";const g=JSON.parse('{"title":"Neural Network Module: System Integration","description":"","frontmatter":{},"headers":[],"relativePath":"ko/advanced/nn_module_utilities.md","filePath":"ko/advanced/nn_module_utilities.md"}'),r={name:"ko/advanced/nn_module_utilities.md"};function s(l,e,h,d,c,m){return i(),a("div",null,e[0]||(e[0]=[n('<h1 id="neural-network-module-system-integration" tabindex="-1">Neural Network Module: System Integration <a class="header-anchor" href="#neural-network-module-system-integration" aria-label="Permalink to &quot;Neural Network Module: System Integration&quot;">​</a></h1><p>The neural control module (<a href="./../modules/modules_controller.html#mc_nn_control">mc_nn_control</a>) implements an end-to-end controller utilizing neural networks.</p><p>The parts of the module directly concerned with generating the code for the trained neural network and integrating it into the module are covered in <a href="./../advanced/tflm.html">TensorFlow Lite Micro (TFLM)</a>. This page covers the changes that were made to integrate the module into PX4, both within the module, and in larger system configuration.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>This topic should help you to shape the module to your own needs.</p><p>You will need some familiarity with PX4 development. For more information see the developer <a href="./../dev_setup/getting_started.html">Getting Started</a>.</p></div><h2 id="자동-실행" tabindex="-1">자동 실행 <a class="header-anchor" href="#자동-실행" aria-label="Permalink to &quot;자동 실행&quot;">​</a></h2><p>A line to autostart the <a href="./../modules/modules_controller.html#mc_nn_control">mc_nn_control</a> module has been added in the <a href="https://github.com/PX4/PX4-Autopilot/blob/main/ROMFS/px4fmu_common/init.d/rc.mc_apps" target="_blank" rel="noreferrer"><code>ROMFS/px4fmu_common/init.d/rc.mc_apps</code></a> startup script.</p><p>It checks whether the module is included by looking for the parameter <a href="./../advanced_config/parameter_reference.html#MC_NN_EN">MC_NN_EN</a>. If this is set to <code>1</code> (the default value), the module will be started when booting PX4. Similarly you could create other parameters in the <a href="https://github.com/PX4/PX4-Autopilot/blob/main/src/modules/mc_nn_control/mc_nn_control_params.c" target="_blank" rel="noreferrer"><code>mc_nn_control_params.c</code></a> file for other startup script checks.</p><h2 id="custom-flight-mode" tabindex="-1">Custom Flight Mode <a class="header-anchor" href="#custom-flight-mode" aria-label="Permalink to &quot;Custom Flight Mode&quot;">​</a></h2><p>The module creates its own flight mode &quot;Neural Control&quot; which lets you choose it from the flight mode menu in QGC and bind it to a switch on you RC controller. This is done by using the <a href="./../ros2/px4_ros2_interface_lib.html">ROS 2 Interface Library</a> internally. This involves several steps and is visualized here:</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The module does not actually use ROS 2, it just uses the API exposed through uORB topics.</p></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>In some QGC versions the flight mode does not show up, so make sure to update to the newest version. This only works for some flight controllers, so you might have to use an RC controller to switch to the correct external flight mode.</p></div><p><img src="'+t+'" alt="neural_mode_registration"></p><ol><li>Publish a <a href="./../msg_docs/RegisterExtComponentRequest.html">RegisterExtComponentRequest</a>. This specifies what you want to create, you can read more about this in the <a href="./../ros2/px4_ros2_control_interface.html">Control Interface</a>. In this case we register an arming check and a mode.</li><li>Wait for a <a href="./../msg_docs/RegisterExtComponentReply.html">RegisterExtComponentReply</a>. This will give feedback on wether the mode registration was successful, and what the mode and arming check id is for the new mode.</li><li>[Optional] With the mode id, publish a <a href="./../msg_docs/VehicleControlMode.html">VehicleControlMode</a> message on the <code>config_control_setpoints</code> topic. Here you can configure what other modules run in parallel. The example controller replaces everything, so it turns off allocation. If you want to replace other parts you can enable or disable the modules accordingly.</li><li>[Optional] With the mode id, publish a <a href="./../msg_docs/ConfigOverrides.html">ConfigOverrides</a> on the <code>config_overrides_request</code> topic. (This is not done in the example module) This will let you defer failsafes or stop it from automatically disarming.</li><li>When the mode has been registered a <a href="./../msg_docs/ArmingCheckRequest.html">ArmingCheckRequest</a> will be sent, asking if your mode has everything it needs to run. This message must be answered with a <a href="./../msg_docs/ArmingCheckReply.html">ArmingCheckReply</a> so the mode is not flagged as unresponsive. In this response it is possible to set what requirements the mode needs to run, like local position. If any of these requirements are set the commander will stop you from switching to the mode if they are not fulfilled. It is also important to set health_component_index and num_events to 0 to not get a segmentation fault. Unless you have a health component or events.</li><li>Listen to the <a href="./../msg_docs/VehicleStatus.html">VehicleStatus</a> topic. If the nav_state equals the assigned <code>mode_id</code>, then the Neural Controller is activated.</li><li>When active the module will run the controller and publish to <a href="./../msg_docs/ActuatorMotors.html">ActuatorMotors</a>. If you want to replace a different part of the controller, you should find the appropriate topic to publish to.</li></ol><p>To see how the requests are handled you can check out <a href="https://github.com/PX4/PX4-Autopilot/blob/main/src/modules/commander/ModeManagement.cpp" target="_blank" rel="noreferrer">src/modules/commander/ModeManagement.cpp</a>.</p><h2 id="로깅" tabindex="-1">로깅 <a class="header-anchor" href="#로깅" aria-label="Permalink to &quot;로깅&quot;">​</a></h2><p>To add module-specific logging a new topic has been added to <a href="./../middleware/uorb.html">uORB</a> called <a href="./../msg_docs/NeuralControl.html">NeuralControl</a>. The message definition is also added in <code>msg/CMakeLists.txt</code>, and to <a href="https://github.com/PX4/PX4-Autopilot/blob/main/src/modules/logger/logged_topics.cpp" target="_blank" rel="noreferrer"><code>src/modules/logger/logged_topics.cpp</code></a> under the debug category. For these messages to be saved in your logs you need to include <code>debug</code> in the <a href="./../advanced_config/parameter_reference.html#SDLOG_PROFILE">SDLOG_PROFILE</a> parameter.</p><h2 id="timing" tabindex="-1">Timing <a class="header-anchor" href="#timing" aria-label="Permalink to &quot;Timing&quot;">​</a></h2><p>The module has two includes for measuring the inference times. The first one is a driver that works on the actual flight controller units, but a second one, <code>chrono</code>, is loaded for SITL testing. Which timing library is included and used is based on wether PX4 is built with NUTTX or not.</p><h2 id="changing-the-setpoint" tabindex="-1">Changing the setpoint <a class="header-anchor" href="#changing-the-setpoint" aria-label="Permalink to &quot;Changing the setpoint&quot;">​</a></h2><p>The module uses the <a href="./../msg_docs/TrajectorySetpoint.html">TrajectorySetpoint</a> message’s position fields to define its target. To follow a trajectory, you can send updated setpoints. For an example of how to do this in a PX4 module, see the <a href="https://github.com/SindreMHegre/PX4-Autopilot-public/tree/main/src/modules/mc_nn_testing" target="_blank" rel="noreferrer">mc_nn_testing</a> module in this fork. Note that this is not included in upstream PX4. To use it, copy the module folder from the linked repository into your workspace, and enable it by adding the following line to your <code>.px4board</code> file:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CONFIG_MODULES_MC_NN_TESTING</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">y</span></span></code></pre></div>',21)]))}const f=o(r,[["render",s]]);export{g as __pageData,f as default};
